B.m9=s(["\u05d9\u05e0\u05d5\u05f3","\u05e4\u05d1\u05e8\u05f3","\u05de\u05e8\u05e5","\u05d0\u05e4\u05e8\u05f3","\u05de\u05d0\u05d9","\u05d9\u05d5\u05e0\u05d9","\u05d9\u05d5\u05dc\u05d9","\u05d0\u05d5\u05d2\u05f3","\u05e1\u05e4\u05d8\u05f3","\u05d0\u05d5\u05e7\u05f3","\u05e0\u05d5\u05d1\u05f3","\u05d3\u05e6\u05de\u05f3"],t.s)
B.bi=new A.Ff(1,"stimmtNicht")
B.bBR=new A.d_("In der Schwangerschaft musst du f\xfcr zwei essen.",B.bi,"Der Energiebedarf steigt nur wenig: im zweiten Drittel um etwa 250, im dritten um etwa 500 Kilokalorien pro Tag. Das entspricht eher einem Zwischenimbiss als einer zweiten Portion.","Netzwerk Gesund ins Leben")
B.bCh=new A.d_("Kaffee ist in der Schwangerschaft komplett verboten.",B.bi,"Bis zu 200 Milligramm Koffein pro Tag gelten als unbedenklich, das sind etwa zwei bis drei Tassen Kaffee.","Bundesinstitut f\xfcr Risikobewertung")
B.bBP=new A.d_("Sex schadet dem Baby.",B.bi,"Bei normalem Verlauf schadet Sex dem Baby nicht. Es ist durch Fruchtwasser und Geb\xe4rmuttermuskel gut gesch\xfctzt. Bei Blutungen, vorzeitigen Wehen oder tiefliegendem Mutterkuchen sprich mit deiner \xc4rztin.","Leitlinien der DGGG")
B.bBM=new A.d_("Ein schneller Herzschlag des Babys bedeutet M\xe4dchen.",B.bi,"Die Herzfrequenz des Babys h\xe4ngt vom Alter und Zustand ab, nicht vom Geschlecht. Das Geschlecht l\xe4sst sich per Ultraschall meist ab der 18. bis 22. Woche erkennen.","familienplanung.de (BI\xd6G)")
B.bC7=new A.d_("Ein spitzer Bauch bedeutet Junge, ein runder Bauch M\xe4dchen.",B.bi,"Die Bauchform h\xe4ngt von K\xf6rperbau, Muskulatur, Lage des Babys und davon ab, ob es dein erstes Kind ist. Sie sagt nichts \xfcber das Geschlecht aus.","familienplanung.de (BI\xd6G)")
B.zs=new A.Ff(3,"nichtBelegt")
B.bC4=new A.d_("Sodbrennen bedeutet, dass das Baby viele Haare hat.",B.zs,"Eine kleine Studie fand einen Zusammenhang, verl\xe4sslich vorherzusagen ist die Haarpracht daraus nicht. Sodbrennen entsteht vor allem durch Hormone und den Druck der Geb\xe4rmutter.","Leitlinien der DGGG")
B.bC9=new A.d_("Sport schadet dem Baby.",B.bi,"Bei unkomplizierter Schwangerschaft wird moderate Bewegung ausdr\xfccklich empfohlen. Verzichten solltest du auf Sportarten mit Sturzrisiko und bei \xe4rztlichem Bewegungsverbot.","Leitlinien der DGGG")
B.bBW=new A.d_("Wer die Arme \xfcber den Kopf hebt, wickelt die Nabelschnur um das Baby.",B.bi,"Die Nabelschnur schlingt sich unabh\xe4ngig von deinen Armbewegungen um das Baby, weil es sich frei im Fruchtwasser bewegt. Du kannst Arme heben, Regale erreichen und W\xe4sche aufh\xe4ngen.","Deutscher Hebammenverband")
B.kA=new A.Ff(2,"teils")
B.bBK=new A.d_("Du darfst auf dem R\xfccken schlafen, das ist nie ein Problem.",B.kA,"Kurzes Liegen ist kein Problem. In der zweiten H\xe4lfte der Schwangerschaft wird die Seitenlage empfohlen, weil die Geb\xe4rmutter in R\xfcckenlage auf gro\xdfe Blutgef\xe4\xdfe dr\xfccken kann. Wachst du auf dem R\xfccken auf, dreh dich einfach um.","Deutscher Hebammenverband")
B.bBV=new A.d_("Wer schwanger ist, muss die Katze abgeben.",B.bi,"Du musst nur Kontakt zum Katzenkot vermeiden (Toxoplasmose). Lass das Katzenklo von jemand anderem reinigen oder trage Handschuhe und wasche danach gr\xfcndlich die H\xe4nde.","Bundesinstitut f\xfcr Risikobewertung")
B.bCc=new A.d_("Haare f\xe4rben ist in der Schwangerschaft verboten.",B.kA,"Gelegentliches F\xe4rben gilt als unbedenklich, weil nur wenig Farbstoff durch die Kopfhaut in den K\xf6rper gelangt. Wer vorsichtig sein will, wartet bis nach dem ersten Drittel und l\xfcftet gut.","Embryotox (Charit\xe9)")
B.bBF=new A.d_("Schwangere d\xfcrfen nicht fliegen.",B.bi,"Bei unkomplizierter Schwangerschaft ist Fliegen meist bis etwa zur 36. Woche m\xf6glich. Airlines verlangen oft ein Attest ab der 28. bis 32. Woche, trage gegen Thrombose Kompressionsstr\xfcmpfe.","Leitlinien der DGGG")
B.bC2=new A.d_("Das Baby kommt am errechneten Termin.",B.bi,"Nur etwa vier von hundert Babys kommen am errechneten Termin. Als termingerecht gilt jede Geburt zwischen der 37+0 und 41+6 SSW.","Mutterschafts-Richtlinien des G-BA")
B.bCd=new A.d_("Bei Vollmond kommen mehr Babys zur Welt.",B.bi,"Untersuchungen mit tausenden Geburten zeigen keinen Zusammenhang zwischen Mondphase und Geburtenzahl. Der Eindruck entsteht durch selektive Erinnerung.",u.bW)
B.bBJ=new A.d_("Jede Schwangerschaft kostet einen Zahn.",B.bi,"Z\xe4hne verlieren in der Schwangerschaft kein Calcium. Allerdings ist das Zahnfleisch empfindlicher, gute Pflege und Kontrolle beim Zahnarzt sind wichtig.","BI\xd6G")
B.bCm=new A.d_("Stillen verh\xfctet zuverl\xe4ssig.",B.bi,"Stillen kann den Eisprung verz\xf6gern, ist aber nur unter sehr engen Bedingungen sicher genug. Der erste Eisprung kommt vor der ersten Periode, du kannst also schwanger werden, ohne es vorher zu merken.","Leitlinien der DGGG")
B.bBL=new A.d_("Stillen l\xe4sst die Br\xfcste h\xe4ngen.",B.bi,"Die Brustform ver\xe4ndert sich vor allem durch die Schwangerschaft selbst, Alter, Gewicht und Veranlagung, nicht durch das Stillen an sich.","Nationale Stillkommission")
B.bBN=new A.d_("Wer nicht stillt, baut keine gute Bindung zum Kind auf.",B.bi,"Bindung entsteht durch N\xe4he, Zuwendung und liebevollen Umgang. Auch mit dem Fl\xe4schchen ist enger K\xf6rperkontakt m\xf6glich und wichtig.","BI\xd6G")
B.bCg=new A.d_("Ein Kaiserschnitt ist der einfachere Weg.",B.bi,"Ein Kaiserschnitt ist eine gro\xdfe Bauchoperation mit l\xe4ngerer Erholung und eigenen Risiken. Er kann medizinisch notwendig und sinnvoll sein, ist aber nicht \u201eeinfacher\u201c.","Leitlinien der DGGG")
B.bCb=new A.d_("Nach einem Kaiserschnitt ist wieder ein Kaiserschnitt n\xf6tig.",B.bi,"Vielen Frauen gelingt nach einem Kaiserschnitt eine vaginale Geburt. Ob sie f\xfcr dich infrage kommt, kl\xe4rt ihr in der Schwangerschaft gemeinsam mit der Klinik.","Leitlinien der DGGG")
B.bBE=new A.d_("Ein Baby braucht Kissen und Decke, um gut zu schlafen.",B.bi,"Kissen, Decken, Nestchen und Kuscheltiere erh\xf6hen die Gefahr des pl\xf6tzlichen Kindstods. Ein Schlafsack in passender Gr\xf6\xdfe auf fester Matratze ist sicher.","BI\xd6G: Sicherer Babyschlaf")
B.bBO=new A.d_("Ein Baby, das viel getragen wird, wird verw\xf6hnt.",B.bi,"Babys k\xf6nnen nicht verw\xf6hnt werden. N\xe4he und rasche Zuwendung geben Sicherheit und f\xf6rdern eine stabile Bindung.","BI\xd6G")
B.bC8=new A.d_("Schreien lassen st\xe4rkt die Lungen.",B.bi,"Schreien lassen hilft nicht, sondern stresst das Baby. Auf Weinen zu reagieren, gibt Sicherheit. Bist du \xfcberfordert, lege dein Baby sicher ab und hole Hilfe.","BI\xd6G")
B.bC1=new A.d_("Zahnen verursacht hohes Fieber und Durchfall.",B.bi,"Beim Zahnen kann es zu Sabbern, Unruhe und leicht erh\xf6hter Temperatur kommen. Hohes Fieber und Durchfall haben eine andere Ursache und sollten abgekl\xe4rt werden.","DGKJ")
B.bC3=new A.d_("Ein Baby schl\xe4ft besser durch, wenn es fr\xfch Brei bekommt.",B.bi,"Fr\xfcher Brei verbessert den Schlaf nachweislich nicht. Beikost beginnt erst, wenn dein Kind bereit ist, fr\xfchestens zu Beginn des 5. Monats. Die Stillleitlinie von 2026 empfiehlt eher etwa sechs Monate Stillen.",u.k)
B.bBQ=new A.d_("Impfungen \xfcberlasten das Immunsystem des Babys.",B.bi,"Babys begegnen t\xe4glich unz\xe4hligen Erregern. Impfstoffe belasten das Immunsystem nicht \xfcberm\xe4\xdfig, sie sch\xfctzen vor gef\xe4hrlichen Krankheiten, gerade in den ersten Monaten.","STIKO / Robert Koch-Institut")
B.bBY=new A.d_("Der pl\xf6tzliche Kindstod l\xe4sst sich nicht beeinflussen.",B.bi,"Das Risiko l\xe4sst sich deutlich senken: R\xfcckenlage, sichere Schlafumgebung, kein Rauch, eigener Schlafplatz im Elternzimmer, Stillen und Schnuller.","BI\xd6G: Sicherer Babyschlaf")
B.bBU=new A.d_("Handystrahlung und WLAN schaden dem ungeborenen Baby.",B.zs,"Nach heutigem Wissen gibt es keinen Hinweis auf Sch\xe4den durch allt\xe4gliche Nutzung. Ein dauerhafter Kontakt des Handys mit dem Bauch ist nicht n\xf6tig.","Bundesamt f\xfcr Strahlenschutz")
B.bC5=new A.d_("Ein Glas Rotwein am Abend ist okay.",B.bi,"Es gibt keine nachweislich sichere Alkoholmenge in der Schwangerschaft. Alkohol geht direkt auf das Baby \xfcber und kann bleibende Sch\xe4den verursachen.","BI\xd6G")
B.bBX=new A.d_("Ingwer hilft gegen Schwangerschafts\xfcbelkeit.",B.kA,"Studien zeigen bei manchen eine leichte Linderung. Er ist in \xfcblichen Mengen unbedenklich. Bei starker \xdcbelkeit ist \xe4rztliche Hilfe n\xf6tig.","Leitlinien der DGGG")
B.bBZ=new A.d_("Himbeerbl\xe4ttertee erleichtert die Geburt.",B.zs,"Ein klarer Nutzen ist nicht belegt. In \xfcblichen Mengen gilt er als unbedenklich, viele Hebammen empfehlen ihn trotzdem gern in den letzten Wochen.","Deutscher Hebammenverband")
B.bC_=new A.d_("Dammmassage senkt das Risiko f\xfcr einen Dammriss.",B.kA,"Bei Erstgeb\xe4renden kann Dammmassage ab der 34. Woche die Wahrscheinlichkeit f\xfcr schwere Risse und Dammschnitte etwas senken. Sie ist freiwillig.","Deutscher Hebammenverband")
B.bC6=new A.d_("Ab dem errechneten Termin muss eingeleitet werden.",B.bi,"Am Termin wird h\xe4ufiger kontrolliert. Eine Einleitung wird meist ab 41+0 angeboten, sp\xe4testens bei Risiken. Ob und wann du einleiten lassen willst, entscheidest du nach Beratung.","Leitlinien der DGGG")
B.bCa=new A.d_("Zwillinge \xfcberspringen eine Generation.",B.bi,"Zweieiige Zwillinge kommen famili\xe4r geh\xe4uft vor, meist \xfcber die Mutterseite, ohne dass eine Generation \xfcbersprungen w\xfcrde. Eineiige Zwillinge sind reiner Zufall.","Pschyrembel")
B.bCl=new A.d_("Neugeborene sehen nur in Schwarz-Wei\xdf.",B.kA,"Neugeborene sehen anfangs verschwommen und erkennen kontrastreiche Muster am besten. Das Farbsehen entwickelt sich in den ersten Monaten. Auf 20 bis 30 Zentimeter sehen sie am sch\xe4rfsten.","Kinder\xe4rzte im Netz")
B.bBH=new A.d_("Ein Baby muss nach dem Essen immer aufsto\xdfen.",B.kA,"Ein B\xe4uerchen kann Bl\xe4hungen lindern, ist aber nicht bei jeder Mahlzeit n\xf6tig. Viele gestillte Babys schlucken wenig Luft. Wenn dein Baby zufrieden ist, brauchst du nicht lange zu warten.","Kinder\xe4rzte im Netz")
B.bBG=new A.d_("Die erste Milch, das Kolostrum, ist minderwertig.",B.bi,"Das Kolostrum ist konzentrierte, an Abwehrstoffen reiche Milch. In kleinen Mengen ist es genau das, was ein Neugeborenes in den ersten Tagen braucht.","Nationale Stillkommission")
B.bCf=new A.d_("Bl\xe4hende Lebensmittel machen das Baby beim Stillen unruhig.",B.bi,"Was du isst, geht nicht in Form von Luft in die Milch \xfcber. Bei Bauchweh des Babys spielt selten deine Ern\xe4hrung eine Rolle. Bei Verdacht auf Unvertr\xe4glichkeit sprich mit der Kinder\xe4rztin.","Nationale Stillkommission")
B.bBI=new A.d_("Sonnenlicht heilt Neugeborenengelbsucht.",B.bi,"Direkte Sonne ist f\xfcr Neugeborene gef\xe4hrlich und keine Behandlung. Eine Gelbsucht wird \xe4rztlich kontrolliert und bei Bedarf mit Lichttherapie unter medizinischer Aufsicht behandelt.","DGKJ")
B.bCk=new A.d_("Wer Gestationsdiabetes hat, bekommt automatisch ein krankes Baby.",B.bi,"Mit Ern\xe4hrung, Bewegung und ggf. Insulin l\xe4sst sich der Blutzucker meist gut einstellen. Unbehandelt kann das Baby zu gro\xdf werden, deshalb ist die Kontrolle wichtig.","Leitlinien der DGGG")
B.bBS=new A.d_("Ohne Schmerzmittel ist eine Geburt \u201erichtiger\u201c.",B.bi,"Es gibt kein richtig oder falsch. Wie du mit Schmerzen umgehst, entscheidest du. Zur Wahl stehen Atmung, Wasser, Massage, Lachgas, PDA und mehr.","Deutscher Hebammenverband")
B.bCj=new A.d_("Schwangere d\xfcrfen nicht die Haare schneiden oder baden.",B.bi,"Haarschneiden und ein warmes Bad sind kein Problem. Sehr hei\xdfe B\xe4der und Saunag\xe4nge solltest du im ersten Drittel meiden.","Leitlinien der DGGG")
B.bBT=new A.d_("Am Ende der Schwangerschaft sollte man sich nur noch schonen.",B.bi,"Bewegung ist weiter gut, Spazierg\xe4nge und leichte Gymnastik tun Kreislauf und Stimmung gut. Als sichere Methode, Wehen auszul\xf6sen, taugt sie allerdings nicht.","Deutscher Hebammenverband")
B.bCe=new A.d_("Wer nicht lange stillt, macht etwas falsch.",B.bi,"Jede Stillzeit ist wertvoll. Die neue S3-Leitlinie von 2026 empfiehlt etwa sechs Monate ausschlie\xdfliches oder \xfcberwiegendes Stillen und insgesamt mindestens zw\xf6lf Monate. Das ist eine Empfehlung, kein Ma\xdfstab f\xfcr dich als Mutter. Klappt Stillen nicht oder m\xf6chtest du nicht, ist Pre-Nahrung eine gute Alternative.",u.R)
B.bCi=new A.d_("Nach der Geburt geh\xf6rt man sofort wieder in Form.",B.bi,"Der K\xf6rper braucht Zeit. Wochenbett und R\xfcckbildung dauern Wochen bis Monate. Ein langsamer Wiedereinstieg sch\xfctzt Beckenboden und Bauchmuskeln.","Deutscher Hebammenverband")
B.bC0=new A.d_("Man kann das Geschlecht am Herzschlag oder an Hei\xdfhunger erkennen.",B.bi,"Weder Hei\xdfhunger auf S\xfc\xdfes oder Saures noch andere Beobachtungen sagen das Geschlecht voraus. Sicher sind nur Ultraschall (ab etwa der 18. Woche) und Erbgutuntersuchungen.","familienplanung.de (BI\xd6G)")
