B.bAg=new A.cp("Bequem hinsetzen","Setz oder leg dich so hin, dass du dich sicher und bequem f\xfchlst. Die Augen d\xfcrfen sich schlie\xdfen.",15)
B.bAw=new A.cp("Den Atem beobachten","Sp\xfcr, wie der Atem von selbst kommt und geht. Du musst nichts ver\xe4ndern.",25)
B.bAE=new A.cp("Der Boden tr\xe4gt dich","Sp\xfcr, wo dein K\xf6rper aufliegt: F\xfc\xdfe, Ges\xe4\xdf, R\xfccken. Lass das Gewicht ab.",25)
B.bAy=new A.cp("Schultern l\xf6sen","Lass die Schultern sinken, auch Kiefer und Stirn d\xfcrfen weich werden.",25)
B.bAs=new A.cp("L\xe4nger ausatmen","Atme durch die Nase ein und etwas l\xe4nger durch den Mund aus. Ein paar Atemz\xfcge lang.",40)
B.bAi=new A.cp("Zur\xfcckkommen","Sp\xfcr noch einmal deinen ganzen K\xf6rper. Beweg Finger und Zehen und \xf6ffne dann langsam die Augen.",25)
B.btb=s([B.bAg,B.bAw,B.bAE,B.bAy,B.bAs,B.bAi],t.hW)
B.bAW=new A.mj("ankommen","Ankommen",B.pd,"Drei Minuten, um im K\xf6rper anzukommen. Gut f\xfcr zwischendurch.",B.btb,!0)
B.bAr=new A.cp("Ankommen","Leg dich bequem hin, in der Schwangerschaft am besten auf die Seite mit einem Kissen zwischen den Knien.",25)
B.bA2=new A.cp("Atem","Sp\xfcr ein paar Atemz\xfcge lang, wie sich dein K\xf6rper mit dem Atem bewegt.",30)
B.bAo=new A.cp("Kopf und Gesicht","Lass Stirn, Augen, Wangen und Kiefer los. Die Zunge liegt weich im Mund.",40)
B.bAI=new A.cp("Nacken und Schultern","Lass Nacken und Schultern schwer werden und in die Unterlage sinken.",40)
B.bAm=new A.cp("Arme und H\xe4nde","Sp\xfcr die Arme bis in die Fingerspitzen. Die H\xe4nde d\xfcrfen ganz weich sein.",40)
B.bAG=new A.cp("Brust und R\xfccken","Sp\xfcr, wie sich der Brustkorb beim Atmen weitet. Lass den R\xfccken getragen sein.",45)
B.bAv=new A.cp("Bauch","Leg eine Hand auf den Bauch. Atme weich dorthin und sp\xfcr die W\xe4rme deiner Hand.",50)
B.bAB=new A.cp("Becken und Beine","Lass Becken und Beckenboden weich werden. Sp\xfcr die Oberschenkel, Knie, Waden.",50)
B.bAF=new A.cp("F\xfc\xdfe","Sp\xfcr die F\xfc\xdfe bis in die Zehen. Lass alles Gewicht abgeben.",35)
B.bAc=new A.cp("Ganzer K\xf6rper","Sp\xfcr jetzt deinen ganzen K\xf6rper als Einheit, ruhig und getragen.",40)
B.bAN=new A.cp("Zur\xfcckkommen","Beweg langsam Finger und Zehen, streck dich und \xf6ffne die Augen. Steh langsam auf, wenn du aufstehst.",30)
B.btz=s([B.bAr,B.bA2,B.bAo,B.bAI,B.bAm,B.bAG,B.bAv,B.bAB,B.bAF,B.bAc,B.bAN],t.hW)
B.bB_=new A.mj("bodyscan","K\xf6rperreise",B.pd,"Vom Kopf bis zu den F\xfc\xdfen: jeden Bereich wahrnehmen und l\xf6sen.",B.btz,!0)
B.bzZ=new A.cp("Vorbereitung","Setz dich bequem hin. Du spannst gleich Muskelgruppen kurz und mit etwa der H\xe4lfte deiner Kraft an und l\xe4sst dann los. Den Bauch l\xe4sst du aus.",25)
B.bA8=new A.cp("H\xe4nde","Ball die H\xe4nde sanft zu F\xe4usten, f\xfcnf Sekunden. Dann loslassen und den Unterschied sp\xfcren.",25)
B.bAA=new A.cp("Arme","Zieh die Ellbogen sanft an den K\xf6rper, halte kurz. Dann loslassen und nachsp\xfcren.",25)
B.bAh=new A.cp("Schultern","Zieh die Schultern zu den Ohren, halte kurz. Dann fallen lassen.",25)
B.bA0=new A.cp("Gesicht","Zieh Stirn und Augen leicht zusammen, halte kurz. Dann alles weich werden lassen.",25)
B.bA6=new A.cp("Ges\xe4\xdf","Spann das Ges\xe4\xdf sanft an, halte kurz. Dann l\xf6sen.",25)
B.bA5=new A.cp("Beine","Streck die Beine, zieh die Zehen zu dir, halte kurz. Dann die Beine ganz schwer werden lassen.",30)
B.bAb=new A.cp("Nachsp\xfcren","Sp\xfcr, wie der ganze K\xf6rper entspannt und schwer ist. Atme ruhig und lang aus.",60)
B.bA7=new A.cp("Zur\xfcckkommen","Streck dich, atme tief ein und \xf6ffne die Augen.",20)
B.bqR=s([B.bzZ,B.bA8,B.bAA,B.bAh,B.bA0,B.bA6,B.bA5,B.bAb,B.bA7],t.hW)
B.bAY=new A.mj("muskelentspannung","Muskeln l\xf6sen",B.pd,"Kurz anspannen, dann loslassen: die Muskelentspannung nach Jacobson, sanft angepasst.",B.bqR,!1)
B.bAp=new A.cp("Bequem hinlegen","Leg dich auf die Seite oder setz dich mit Kissen im R\xfccken. Beide H\xe4nde liegen am Bauch.",20)
B.bAz=new A.cp("Atem","Atme ruhig ein und aus. Sp\xfcr, wie sich der Bauch unter deinen H\xe4nden sanft hebt und senkt.",45)
B.bAO=new A.cp("W\xe4rme sp\xfcren","Sp\xfcr die W\xe4rme deiner H\xe4nde. Du darfst dir vorstellen, dass dein Baby sie sp\xfcrt.",40)
B.bAK=new A.cp("Bewegung wahrnehmen","Wenn du dein Baby sp\xfcrst, verweil bei der Bewegung. Wenn nicht, ist das auch in Ordnung. Nicht jede Zeit ist Bewegungszeit.",45)
B.bzY=new A.cp("Ein Satz f\xfcr dein Baby","Sag innerlich einen freundlichen Satz, zum Beispiel: \u201eIch freue mich auf dich.\u201c",40)
B.bAx=new A.cp("Dankbarkeit","Denk an etwas, das du an dir und deinem K\xf6rper gerade wertsch\xe4tzt.",40)
B.bAl=new A.cp("Abschluss","Atme tief ein, streck dich und \xf6ffne die Augen. Nimm die Ruhe mit.",25)
B.bl0=s([B.bAp,B.bAz,B.bAO,B.bAK,B.bzY,B.bAx,B.bAl],t.hW)
B.bAU=new A.mj("baby-verbindung","Verbindung zu deinem Baby",B.a56,"Hand auf den Bauch, ruhig atmen und Kontakt zu deinem Kind aufnehmen.",B.bl0,!1)
B.bAL=new A.cp("Zur Ruhe kommen","Leg dich in deine bequemste Schlafposition. Die Schwangerschaft: am besten auf der Seite, mit Kissen. Lass das Licht gedimmt.",30)
B.bA9=new A.cp("Lang ausatmen","Atme vier Sekunden ein und sechs Sekunden aus. Wiederhole das ruhig.",60)
B.bA4=new A.cp("Gedanken ziehen lassen","Kommen Gedanken, lass sie wie Wolken vorbeiziehen. Du musst heute nichts mehr l\xf6sen.",60)
B.bA1=new A.cp("Schwer werden","Sp\xfcr, wie Arme und Beine schwer werden und in die Matratze sinken.",60)
B.bAu=new A.cp("Ein ruhiger Ort","Stell dir einen Ort vor, an dem du dich sicher f\xfchlst. Sp\xfcr die W\xe4rme und Stille dort.",90)
B.bAH=new A.cp("Loslassen","Lass jetzt den Atem ganz von allein gehen. Du darfst einschlafen.",120)
B.brH=s([B.bAL,B.bA9,B.bA4,B.bA1,B.bAu,B.bAH],t.hW)
B.bAV=new A.mj("einschlafen","Zum Einschlafen",B.a57,"Langsam abschalten: Atem, K\xf6rper, sanfte Bilder.",B.brH,!0)
B.bA3=new A.cp("Ankommen","Setz dich bequem hin oder lehn dich an. Sp\xfcr deine F\xfc\xdfe und deinen Atem.",25)
B.bAP=new A.cp("Die Welle kommt","Stell dir vor, eine Welle baut sich auf. Atme ruhig ein und beim Ausatmen lang und tief aus, leise t\xf6nend (\u201eooo\u201c).",40)
B.bAR=new A.cp("Auf der Welle","Bleib auf dem Ausatmen. Lass Kiefer, Schultern und H\xe4nde locker. Spannung darf da sein.",40)
B.bAa=new A.cp("Die Welle geht","Stell dir vor, die Welle l\xe4uft aus. Atme tief ein und lass die Anspannung mit dem Ausatmen gehen.",40)
B.bAC=new A.cp("Pause zwischen den Wellen","Zwischen den Wellen ruhst du. Atme normal und lass alles los.",30)
B.bAf=new A.cp("Noch eine Welle","Wiederhole: ruhig einatmen, lang ausatmen, t\xf6nen, Kiefer locker.",50)
B.bAk=new A.cp("Nachsp\xfcren","Sp\xfcr nach, wie du auf jede Welle mit Ruhe und Atem antworten kannst. Sie kommen und gehen.",40)
B.bo5=s([B.bA3,B.bAP,B.bAR,B.bAa,B.bAC,B.bAf,B.bAk],t.hW)
B.bAX=new A.mj("wellen-atmen","Wie eine Welle",B.a58,"\xdcbung f\xfcr die Geburtsvorbereitung: Spannung kommt und geht wie eine Welle.",B.bo5,!1)
B.bAJ=new A.cp("Ankommen","Setz dich bequem hin und atme dreimal tief aus.",20)
